def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform row or column separating the two panels.
    split = None
    for r in range(h):
        if len(set(grid[r])) == 1 and 0 < r < h - 1:
            if r == h - 1 - r:
                split = ("row", r)
                break
    if split is None:
        for c in range(w):
            if all(grid[r][c] == grid[0][c] for r in range(h)) and 0 < c < w - 1:
                if c == w - 1 - c:
                    split = ("col", c)
                    break

    if split is None:
        return grid

    if split[0] == "row":
        k = split[1]
        panels = [grid[:k], grid[k + 1:]]
    else:
        k = split[1]
        panels = [
            [row[:k] for row in grid],
            [row[k + 1:] for row in grid],
        ]

    def dominant_fraction(panel):
        from collections import Counter
        counts = Counter(v for row in panel for v in row)
        return max(counts.values()) / sum(counts.values())

    # The target panel is the one with a single dominant background color
    # and sparse contrasting marks.
    if dominant_fraction(panels[0]) > dominant_fraction(panels[1]):
        target, template = panels[0], panels[1]
    else:
        target, template = panels[1], panels[0]

    from collections import Counter
    counts = Counter(v for row in target for v in row)
    background = counts.most_common(1)[0][0]
    marks = [v for v, _ in counts.most_common() if v != background]
    mark_color = marks[0] if marks else background

    out = [[mark_color for _ in row] for row in target]
    for r in range(len(target)):
        for c in range(len(target[0])):
            if target[r][c] == mark_color and template[r][c] == mark_color:
                out[r][c] = 3
    return out
